initial_files.stats.py:
def median(values):
    if not values:
        return 0.0
    s = sorted(values)
    n = len(s)
    if n % 2 == 1: return float(s[n//2])
    return (s[n//2 - 1] + s[n//2]) / 2

oracle_files.stats.py:
def median(values):
    if not values:
        return None
    s = sorted(values)
    n = len(s)
    if n % 2 == 1: return float(s[n//2])
    return (s[n//2 - 1] + s[n//2]) / 2

